/*
 * Clean-room reimplementation of the observed cmatrix executable behavior.
 * This code was written from documented/CLI behavior, not from original source.
 */
#define _POSIX_C_SOURCE 200809L
#include <ctype.h>
#include <errno.h>
#include <fcntl.h>
#include <getopt.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/select.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <sys/types.h>
#include <termios.h>
#include <time.h>
#include <unistd.h>

static const char *USAGE_TEXT =
" Usage: cmatrix -[abBcfhlsmVxk] [-u delay] [-C color] [-t tty] [-M message]\n"
" -a: Asynchronous scroll\n"
" -b: Bold characters on\n"
" -B: All bold characters (overrides -b)\n"
" -c: Use Japanese characters as seen in the original matrix. Requires appropriate fonts\n"
" -f: Force the linux $TERM type to be on\n"
" -l: Linux mode (uses matrix console font)\n"
" -L: Lock mode (can be closed from another terminal)\n"
" -o: Use old-style scrolling\n"
" -h: Print usage and exit\n"
" -n: No bold characters (overrides -b and -B, default)\n"
" -s: \"Screensaver\" mode, exits on first keystroke\n"
" -x: X window mode, use if your xterm is using mtx.pcf\n"
" -V: Print version information and exit\n"
" -M [message]: Prints your message in the center of the screen. Overrides -L's default message.\n"
" -u delay (0 - 10, default 4): Screen update delay\n"
" -C [color]: Use this color for matrix (default green)\n"
" -r: rainbow mode\n"
" -m: lambda mode\n"
" -k: Characters change while scrolling. (Works without -o opt.)\n"
" -t [tty]: Set tty to use\n";

static const char *VERSION_TEXT =
" CMatrix version 2.0 (compiled 19:59:42, Apr 17 2026)\n"
"Email: abishekvashok@gmail.com\n"
"Web: https://github.com/abishekvashok/cmatrix\n";

static const char *INVALID_COLOR_TEXT =
" Invalid color selection\n"
" Valid colors are green, red, blue, white, yellow, cyan, magenta and black.\n";

typedef enum {
    COLOR_BLACK = 30,
    COLOR_RED = 31,
    COLOR_GREEN = 32,
    COLOR_YELLOW = 33,
    COLOR_BLUE = 34,
    COLOR_MAGENTA = 35,
    COLOR_CYAN = 36,
    COLOR_WHITE = 37
} MatrixColor;

typedef struct {
    bool async_scroll;
    int bold_mode;            /* 0 none, 1 random, 2 all */
    bool force_linux;
    bool linux_mode;
    bool old_style;
    bool japanese;
    bool lock_mode;
    bool screensaver;
    bool x_window;
    bool rainbow;
    bool lambda_mode;
    bool change_all;
    int update;
    MatrixColor color;
    const char *message;
    const char *tty_path;
} Options;

typedef struct {
    int y;
    int length;
    int speed;
    int delay_count;
    int active;
} Column;

static FILE *outfp = NULL;
static int outfd = STDOUT_FILENO;
static int tty_input_fd = STDIN_FILENO;
static bool initialized_screen = false;
static bool raw_set = false;
static struct termios old_termios;
static int screen_rows = 24;
static int screen_cols = 80;
static bool force_linux_global = false;

static void cleanup_screen(void);

static void die_write(FILE *fp, const char *s) {
    fputs(s, fp);
}

static int str_case_equal(const char *a, const char *b) {
    if (!a || !b) return 0;
    while (*a && *b) {
        if (tolower((unsigned char)*a) != tolower((unsigned char)*b)) return 0;
        a++; b++;
    }
    return *a == '\0' && *b == '\0';
}

static int parse_color(const char *s, MatrixColor *c) {
    if (str_case_equal(s, "green"))   { *c = COLOR_GREEN; return 1; }
    if (str_case_equal(s, "red"))     { *c = COLOR_RED; return 1; }
    if (str_case_equal(s, "blue"))    { *c = COLOR_BLUE; return 1; }
    if (str_case_equal(s, "white"))   { *c = COLOR_WHITE; return 1; }
    if (str_case_equal(s, "yellow"))  { *c = COLOR_YELLOW; return 1; }
    if (str_case_equal(s, "cyan"))    { *c = COLOR_CYAN; return 1; }
    if (str_case_equal(s, "magenta")) { *c = COLOR_MAGENTA; return 1; }
    if (str_case_equal(s, "black"))   { *c = COLOR_BLACK; return 1; }
    return 0;
}

static void get_screen_size(void) {
    struct winsize ws;
    if (ioctl(outfd, TIOCGWINSZ, &ws) == 0 && ws.ws_row > 0 && ws.ws_col > 0) {
        screen_rows = ws.ws_row;
        screen_cols = ws.ws_col;
        return;
    }
    const char *l = getenv("LINES");
    const char *c = getenv("COLUMNS");
    if (l && atoi(l) > 0) screen_rows = atoi(l);
    if (c && atoi(c) > 0) screen_cols = atoi(c);
    if (screen_rows < 1) screen_rows = 24;
    if (screen_cols < 1) screen_cols = 80;
}

static void outprintf(const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    vfprintf(outfp ? outfp : stdout, fmt, ap);
    va_end(ap);
}

static void flushout(void) {
    fflush(outfp ? outfp : stdout);
}

static void signal_handler(int sig) {
    (void)sig;
    cleanup_screen();
    _exit(0);
}

static void setup_raw_input(void) {
    if (isatty(STDIN_FILENO)) {
        if (tcgetattr(STDIN_FILENO, &old_termios) == 0) {
            struct termios t = old_termios;
            t.c_lflag &= (tcflag_t)~(ICANON | ECHO);
            t.c_cc[VMIN] = 0;
            t.c_cc[VTIME] = 0;
            if (tcsetattr(STDIN_FILENO, TCSANOW, &t) == 0) raw_set = true;
        }
    }
}

static void restore_raw_input(void) {
    if (raw_set) {
        tcsetattr(STDIN_FILENO, TCSANOW, &old_termios);
        raw_set = false;
    }
}

static void init_screen(void) {
    if (initialized_screen) return;
    get_screen_size();

    /* These are the terminfo/xterm sequences produced by ncurses for this program. */
    if (force_linux_global) {
        outprintf("\033)0\033[1;%dr\033[m\017\033[4l\033[?7h\033[?25l", screen_rows);
        outprintf("\033[39;49m\033[39;49m\033[m\017\033[H\033[J");
    } else {
        outprintf("\033[?1049h\033[22;0;0t\033[1;%dr\033(B\033[m\033[4l\033[?7h\033[?25l", screen_rows);
        outprintf("\033[39;49m\033[39;49m\033(B\033[m\033[H\033[2J");
    }
    flushout();
    initialized_screen = true;
}

static void cleanup_screen(void) {
    if (!initialized_screen) {
        restore_raw_input();
        if (outfp) fflush(outfp);
        return;
    }
    if (force_linux_global) {
        outprintf("\033[%d;1H\033[?25h\033[?0c\r", screen_rows);
    } else {
        outprintf("\033[?12l\033[?25h\033[%d;1H\033[?1049l\033[23;0;0t\r\033[?1l\033>", screen_rows);
    }
    flushout();
    initialized_screen = false;
    restore_raw_input();
}

static int key_available(void) {
    fd_set set;
    struct timeval tv;
    FD_ZERO(&set);
    FD_SET(tty_input_fd, &set);
    tv.tv_sec = 0;
    tv.tv_usec = 0;
    int r = select(tty_input_fd + 1, &set, NULL, NULL, &tv);
    return r > 0 && FD_ISSET(tty_input_fd, &set);
}

static int read_key(void) {
    unsigned char ch;
    ssize_t n = read(tty_input_fd, &ch, 1);
    if (n == 1) return ch;
    return -1;
}

static char random_ascii_char(void) {
    static const char chars[] =
        "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"
        "!@#$%^&*()-_=+[]{};:'\"\\|,<.>/?`~";
    return chars[rand() % (int)(sizeof(chars) - 1)];
}

static const char *random_x_char(void) {
    static const char *chars[] = {"0", "1", "2", "3", "A", "B", "C", "D", "E", "F", "G", "H"};
    return chars[rand() % (int)(sizeof(chars) / sizeof(chars[0]))];
}

static const char *random_japanese_char(void) {
    static const char *chars[] = {
        "ｱ", "ｲ", "ｳ", "ｴ", "ｵ", "ｶ", "ｷ", "ｸ", "ｹ", "ｺ", "ｻ", "ｼ", "ｽ", "ｾ", "ｿ",
        "ﾀ", "ﾁ", "ﾂ", "ﾃ", "ﾄ", "ﾅ", "ﾆ", "ﾇ", "ﾈ", "ﾉ", "ﾊ", "ﾋ", "ﾌ", "ﾍ", "ﾎ"
    };
    return chars[rand() % (int)(sizeof(chars) / sizeof(chars[0]))];
}

static const char *choose_glyph(const Options *opt, char *buf, size_t bufsz) {
    if (opt->lambda_mode) return "λ";
    if (opt->japanese) return random_japanese_char();
    if (opt->x_window) return random_x_char();
    snprintf(buf, bufsz, "%c", random_ascii_char());
    return buf;
}

static int rainbow_color_for_col(int col, int tick) {
    static const int colors[] = {32, 33, 34, 35, 36};
    return colors[(col / 2 + tick) % (int)(sizeof(colors) / sizeof(colors[0]))];
}

static void sgr_color(int color, bool bold) {
    if (bold) outprintf("\033[0;1m");
    outprintf("\033[%dm", color);
}

static void draw_initial_blank(const Options *opt) {
    int color = opt->color;
    if (opt->rainbow) color = COLOR_GREEN;
    for (int r = 1; r <= screen_rows; r++) {
        if (r == 1) outprintf("\033[H"); else outprintf("\r\033[%dd", r);
        for (int c = 1; c <= screen_cols; c++) {
            outprintf("\033[%dm \033[39m", color);
            if (!force_linux_global) outprintf("\033(B");
            outprintf("\033[m ");
            c++;
        }
    }
    flushout();
}

static void draw_message(const char *message) {
    if (!message || !*message) return;
    int len = (int)strlen(message);
    int row = screen_rows / 2;
    if (row < 1) row = 1;
    int col = (screen_cols - len) / 2 - 1;
    if (col < 1) col = 1;
    outprintf("\033[%d;%dH\033[37m  %s  \033[39m", row, col, message);
    if (!force_linux_global) outprintf("\033(B");
    outprintf("\033[m");
}

static void init_columns(Column *cols, int n, const Options *opt) {
    for (int i = 0; i < n; i++) {
        cols[i].y = -(rand() % (screen_rows + 1));
        cols[i].length = 3 + rand() % (screen_rows > 6 ? screen_rows / 2 : 4);
        cols[i].speed = opt->async_scroll ? (1 + rand() % 3) : 1;
        cols[i].delay_count = rand() % cols[i].speed;
        cols[i].active = (rand() % 100) < 70;
    }
}

static void restart_column(Column *col, const Options *opt) {
    col->y = -(rand() % screen_rows);
    col->length = 3 + rand() % (screen_rows > 6 ? screen_rows / 2 : 4);
    col->speed = opt->async_scroll ? (1 + rand() % 3) : 1;
    col->delay_count = 0;
    col->active = (rand() % 100) < 85;
}

static void draw_cell(int row, int col, int color, bool bold, const char *glyph) {
    if (row < 1 || row > screen_rows || col < 1 || col > screen_cols) return;
    outprintf("\033[%d;%dH", row, col);
    sgr_color(color, bold);
    outprintf("%s", glyph);
    outprintf("\033[39m");
    if (!force_linux_global) outprintf("\033(B");
    outprintf("\033[m");
}

static void clear_cell(int row, int col) {
    if (row < 1 || row > screen_rows || col < 1 || col > screen_cols) return;
    outprintf("\033[%d;%dH ", row, col);
}

static void handle_key(Options *opt, int ch, bool *done) {
    if (ch < 0) return;
    if (opt->screensaver) { *done = true; return; }
    if (ch == 'q') {
        if (!opt->lock_mode) *done = true;
        return;
    }
    switch (ch) {
        case 'a': opt->async_scroll = !opt->async_scroll; break;
        case 'b': opt->bold_mode = 1; break;
        case 'B': opt->bold_mode = 2; break;
        case 'n': opt->bold_mode = 0; break;
        case '!': opt->color = COLOR_RED; opt->rainbow = false; break;
        case '@': opt->color = COLOR_GREEN; opt->rainbow = false; break;
        case '#': opt->color = COLOR_YELLOW; opt->rainbow = false; break;
        case '$': opt->color = COLOR_BLUE; opt->rainbow = false; break;
        case '%': opt->color = COLOR_MAGENTA; opt->rainbow = false; break;
        case '^': opt->color = COLOR_CYAN; opt->rainbow = false; break;
        case '&': opt->color = COLOR_WHITE; opt->rainbow = false; break;
        case ')': opt->color = COLOR_BLACK; opt->rainbow = false; break;
        default:
            if (ch >= '0' && ch <= '9') opt->update = ch - '0';
            break;
    }
}

static void sleep_update(int update) {
    if (update < 0) update = 0;
    /* The observed program uses small integer delays; atoi values above 10 simply slow it down. */
    long usec = (long)update * 10000L;
    if (usec < 1000L) usec = 1000L;
    if (usec > 2000000L) usec = 2000000L;
    usleep((useconds_t)usec);
}

static void animation_loop(Options opt) {
    force_linux_global = opt.force_linux;
    outfp = stdout;
    outfd = STDOUT_FILENO;

    if (opt.tty_path) {
        int fd = open(opt.tty_path, O_WRONLY | O_NOCTTY);
        if (fd < 0) {
            fprintf(stderr, "cmatrix: error: '%s' couldn't be opened: %s.\n", opt.tty_path, strerror(errno));
            exit(1);
        }
        FILE *fp = fdopen(fd, "w");
        if (!fp) {
            fprintf(stderr, "cmatrix: error: '%s' couldn't be opened: %s.\n", opt.tty_path, strerror(errno));
            close(fd);
            exit(1);
        }
        outfp = fp;
        outfd = fd;
    }

    const char *term = getenv("TERM");
    if ((!term || !*term || strcmp(term, "unknown") == 0) && !opt.force_linux) {
        fprintf(stderr, "Error opening terminal: unknown.\n");
        if (outfp && outfp != stdout) fclose(outfp);
        exit(1);
    }

    if (opt.linux_mode) {
        /* On the benchmark system the font utilities are unavailable; the observed binary prints this. */
        init_screen();
        cleanup_screen();
        fprintf(stderr, " Unable to use both \"setfont\" and \"consolechars\".\n");
        if (outfp && outfp != stdout) fclose(outfp);
        exit(0);
    }

    signal(SIGTERM, signal_handler);
    signal(SIGINT, signal_handler);
    signal(SIGHUP, signal_handler);

    setup_raw_input();
    init_screen();

    bool done = false;
    while (key_available()) {
        int ch = read_key();
        handle_key(&opt, ch, &done);
        if (done) break;
    }
    if (done) {
        outprintf("\033[H\033[2J");
        cleanup_screen();
        if (outfp && outfp != stdout) fclose(outfp);
        return;
    }

    draw_initial_blank(&opt);

    int ncols = screen_cols;
    Column *cols = calloc((size_t)ncols, sizeof(Column));
    if (!cols) {
        cleanup_screen();
        if (outfp && outfp != stdout) fclose(outfp);
        exit(1);
    }
    init_columns(cols, ncols, &opt);

    int tick = 0;
    while (!done) {
        while (key_available()) {
            int ch = read_key();
            handle_key(&opt, ch, &done);
            if (done) break;
        }
        if (done) break;

        if (opt.old_style) {
            /* A simple old-style full-screen scroll approximation. */
            outprintf("\033[H\033D");
        }

        int step = opt.x_window ? 1 : 2;
        if (step < 1) step = 1;
        for (int c = 1; c <= screen_cols; c += step) {
            Column *col = &cols[c - 1];
            if (!col->active) {
                if ((rand() % 100) < 3) restart_column(col, &opt);
                continue;
            }
            col->delay_count++;
            if (col->delay_count < col->speed) continue;
            col->delay_count = 0;

            int color = opt.rainbow ? rainbow_color_for_col(c, tick) : opt.color;
            char one[8];
            const char *glyph = choose_glyph(&opt, one, sizeof(one));
            bool allbold = opt.bold_mode == 2;
            bool randbold = opt.bold_mode == 1 && ((rand() % 3) == 0);
            bool bold = allbold || randbold;

            if (opt.change_all) {
                for (int rr = 1; rr <= screen_rows; rr++) {
                    if ((rand() % 100) < 12) {
                        const char *g2 = choose_glyph(&opt, one, sizeof(one));
                        draw_cell(rr, c, color, bold, g2);
                    }
                }
            }

            int head = col->y;
            int tail = col->y - col->length;
            if (tail >= 1) clear_cell(tail, c);
            if (head >= 1 && head <= screen_rows) {
                if (!opt.japanese && opt.color != COLOR_WHITE && !opt.screensaver) {
                    if (!opt.japanese && !opt.lambda_mode && !opt.rainbow && !opt.old_style && !opt.change_all) {
                        /* white lead characters are a characteristic part of the default display */
                        if ((rand() % 2) == 0) draw_cell(head, c, COLOR_WHITE, bold, glyph);
                        else draw_cell(head, c, color, bold, glyph);
                    } else {
                        draw_cell(head, c, color, bold, glyph);
                    }
                } else {
                    draw_cell(head, c, color == COLOR_BLACK ? COLOR_WHITE : color, bold, glyph);
                }
            }
            int body = col->y - 1;
            if (body >= 1 && body <= screen_rows) {
                const char *g3 = choose_glyph(&opt, one, sizeof(one));
                draw_cell(body, c, color == COLOR_BLACK ? COLOR_BLACK : color, bold, g3);
            }

            col->y++;
            if (col->y - col->length > screen_rows) restart_column(col, &opt);
        }
        if (opt.message) draw_message(opt.message);
        flushout();
        sleep_update(opt.update);
        tick++;
    }

    free(cols);
    outprintf("\033[H\033[2J");
    cleanup_screen();
    if (outfp && outfp != stdout) fclose(outfp);
}

int main(int argc, char **argv) {
    Options opt;
    memset(&opt, 0, sizeof(opt));
    opt.update = 4;
    opt.color = COLOR_GREEN;
    opt.bold_mode = 0;

    opterr = 0;
    int ch;
    while ((ch = getopt(argc, argv, "abBcfhlLo?nsmVxkru:C:M:t:")) != -1) {
        switch (ch) {
            case 'a': opt.async_scroll = true; break;
            case 'b': opt.bold_mode = 1; break;
            case 'B': opt.bold_mode = 2; break;
            case 'c': opt.japanese = true; break;
            case 'f': opt.force_linux = true; break;
            case 'h': case '?': die_write(stdout, USAGE_TEXT); return 0;
            case 'l': opt.linux_mode = true; break;
            case 'L': opt.lock_mode = true; if (!opt.message) opt.message = "Computer locked."; break;
            case 'o': opt.old_style = true; break;
            case 'n': opt.bold_mode = 0; break;
            case 's': opt.screensaver = true; break;
            case 'm': opt.lambda_mode = true; break;
            case 'V': die_write(stdout, VERSION_TEXT); return 0;
            case 'x': opt.x_window = true; break;
            case 'k': opt.change_all = true; break;
            case 'r': opt.rainbow = true; break;
            case 'u': opt.update = atoi(optarg ? optarg : "0"); break;
            case 'C':
                if (!parse_color(optarg, &opt.color)) {
                    die_write(stderr, INVALID_COLOR_TEXT);
                    return 0;
                }
                break;
            case 'M': opt.message = optarg; break;
            case 't': opt.tty_path = optarg; break;
            default: die_write(stdout, USAGE_TEXT); return 0;
        }
    }

    /* getopt returns '?' for unknown options and missing required arguments above. */
    srand((unsigned int)(time(NULL) ^ getpid()));
    animation_loop(opt);
    return 0;
}
