    COLOR_BLACK = 30,
    COLOR_RED = 31,
    COLOR_GREEN = 32,
    COLOR_YELLOW = 33,
    COLOR_BLUE = 34,
    COLOR_MAGENTA = 35,
    COLOR_CYAN = 36,
    COLOR_WHITE = 37
} MatrixColor;

typedef struct {
    bool async_scroll;
    int bold_mode;            /* 0 none, 1 random, 2 all */
    bool force_linux;
    bool linux_mode;
    bool old_style;
    bool japanese;
